// Builds the browser scripts and writes them into the API Worker as strings:
//   apps/api/src/generated/checkout-assets.ts  (PAGE_JS for /p/:id, WIDGET_JS for /v1/checkout.js)
// `node build.mjs --check` fails if the generated file is stale or checkout.js is over 15 KB gzipped.
import { build } from 'esbuild';
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { gzipSync } from 'node:zlib';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const out = join(here, '../api/src/generated/checkout-assets.ts');
const LIMIT = 15 * 1024;

async function bundle(entry) {
	const r = await build({
		entryPoints: [join(here, 'src', entry)],
		bundle: true,
		minify: true,
		format: 'iife',
		target: ['es2018', 'chrome61', 'safari12'],
		write: false,
		legalComments: 'none',
		charset: 'utf8',
	});
	return r.outputFiles[0].text.trim();
}

const page = await bundle('page.ts');
const widget = await bundle('widget.ts');
const gz = (s) => gzipSync(Buffer.from(s)).length;
const text =
	'// Generated by apps/checkout/build.mjs. Do not edit; run `npm run build -w @autoconfirm/checkout`.\n' +
	`export const PAGE_JS = ${JSON.stringify(page)};\n` +
	`export const WIDGET_JS = ${JSON.stringify(widget)};\n` +
	`export const WIDGET_GZIP_BYTES = ${gz(widget)};\n`;

console.log(`page.js ${page.length} B (${gz(page)} B gzipped), checkout.js ${widget.length} B (${gz(widget)} B gzipped, limit ${LIMIT})`);
if (gz(widget) > LIMIT) {
	console.error('checkout.js is over the 15 KB gzipped limit');
	process.exit(1);
}
if (process.argv.includes('--check')) {
	let current = '';
	try {
		current = readFileSync(out, 'utf8');
	} catch {}
	if (current !== text) {
		console.error('apps/api/src/generated/checkout-assets.ts is stale: run npm run build -w @autoconfirm/checkout');
		process.exit(1);
	}
	console.log('generated assets are up to date');
} else {
	mkdirSync(dirname(out), { recursive: true });
	writeFileSync(out, text);
	console.log('wrote', out);
}
